/* Age in whole days at a given instant, from the article's own publication date. */
function ageDays(publishedAt, now = Date.now()) {
  return Math.floor((now - Date.parse(publishedAt)) / 86400000);
}

/*
 * The honest freshness report is a HISTOGRAM, not a pass/fail number. Some predictions —
 * the 2040 Dyson precursors, the Transcension and ruliad horizons — will never have
 * genuine authoritative coverage in a two-week window, and reporting a single freshness
 * score would hide that rather than state it.
 */
const FRESHNESS_BUCKETS = ['<=14d', '15-30d', '31-90d', '91-365d', '>1yr'];

function freshnessBucket(publishedAt, now = Date.now()) {
  const age = ageDays(publishedAt, now);
  if (age <= 14) return '<=14d';
  if (age <= 30) return '15-30d';
  if (age <= 90) return '31-90d';
  if (age <= 365) return '91-365d';
  return '>1yr';
}

/* Plain language, because "P90D" is not something a reader should have to decode. */
function describeAge(publishedAt, now = Date.now()) {
  const age = ageDays(publishedAt, now);
  if (age <= 0) return 'published today';
  if (age === 1) return 'published yesterday';
  if (age < 14) return `published ${age} days ago`;
  if (age < 61) return `published ${Math.round(age / 7)} weeks ago`;
  if (age < 365) return `published ${Math.round(age / 30)} months ago`;
  const years = (age / 365).toFixed(1).replace(/\.0$/, '');
  return `published ${years} year${years === '1' ? '' : 's'} ago`;
}

